css:
/* Prefer NYSDS components, utility classes, and var(--nys-...) tokens
   over custom CSS. This is the only rule this slide needs. */
.intro {
  max-width: 60ch;
}

js:
// Every NYSDS component fires its own events. Listen for them here.
document.querySelectorAll('nys-button').forEach((button) => {
  button.addEventListener('nys-click', () => {
    console.log('You chose:', button.getAttribute('label'));
  });
});
